    -30, -30, 0, 0, 0, 0, -30, -30,
    -50, -30, -30, -30, -30, -30, -30, -50,
)

PST = {
    chess.PAWN: PAWN_T,
    chess.KNIGHT: KNIGHT_T,
    chess.BISHOP: BISHOP_T,
    chess.ROOK: ROOK_T,
    chess.QUEEN: QUEEN_T,
}


class Timeout(Exception):
    pass


class Searcher:
    def __init__(self):
        self.nodes = 0
        self.deadline = 0.0
        self.tt = {}
        self.killers = [[None, None] for _ in range(128)]
        self.history = [[0] * 64 for _ in range(64)]

    def check_time(self):
        if (self.nodes & 1023) == 0 and time.perf_counter() > self.deadline:
            raise Timeout()

    # -- evaluation: score from side-to-move perspective (centipawns) --
    def evaluate(self, board):
        score = 0
        pmap = board.piece_map()
        queens = 0
        other_mat = 0
        for sq, piece in pmap.items():
            pt = piece.piece_type
            if pt == chess.QUEEN:
                queens += 1
            elif pt != chess.PAWN and pt != chess.KING:
                other_mat += PIECE_VAL[pt]
        endgame = queens == 0 or (queens <= 2 and other_mat <= 1300)
        king_t = KING_EG_T if endgame else KING_MG_T
        for sq, piece in pmap.items():
            pt = piece.piece_type
            if pt == chess.KING:
                b = king_t[sq] if piece.color == chess.WHITE else king_t[sq ^ 56]
                v = b
            else:
                t = PST[pt]
                if piece.color == chess.WHITE:
                    v = PIECE_VAL[pt] + t[sq]
                else:
                    v = PIECE_VAL[pt] + t[sq ^ 56]
                if piece.color == chess.WHITE:
                    score += v
                else:
                    score -= v
                continue
            if piece.color == chess.WHITE:
                score += v
            else:
                score -= v
        # tempo bonus
        score += 10
        return score if board.turn == chess.WHITE else -score

    # -- move ordering --
    def order_score(self, board, move, ply, tt_move):
        if move == tt_move:
            return 1 << 30
        s = 0
        if board.is_capture(move):
            cap = board.piece_at(move.to_square)
            cap_v = PIECE_VAL.get(cap.piece_type, 0) if cap else 0
            if board.is_en_passant(move):
                cap_v = PIECE_VAL[chess.PAWN]
            attacker = board.piece_at(move.from_square)
            att_v = PIECE_VAL.get(attacker.piece_type, 1) if attacker else 1
            s = 100000 + cap_v * 10 - att_v
        elif move.promotion:
            s = 90000 + PIECE_VAL.get(move.promotion, 0)
        else:
            k = self.killers[ply] if ply < len(self.killers) else (None, None)
            if move == k[0]:
                s = 80000
            elif move == k[1]:
                s = 70000
            else:
                s = self.history[move.from_square][move.to_square]
        return s

    def ordered_moves(self, board, ply, tt_move, captures_only=False):
        moves = list(board.legal_moves)
        if captures_only:
            moves = [m for m in moves if board.is_capture(m) or m.promotion]
        scored = [(self.order_score(board, m, ply, tt_move), m) for m in moves]
        scored.sort(key=lambda x: -x[0])
        return [m for _, m in scored]

    # -- quiescence (captures + promotions only) --
    def quiesce(self, board, alpha, beta, ply):
        self.nodes += 1
        self.check_time()
        if board.is_checkmate():
            return -(MATE - ply)
        if (board.is_stalemate() or board.is_insufficient_material()
                or board.can_claim_fifty_moves()):
            return 0
        stand = self.evaluate(board)
        if stand >= beta:
            return beta
        if stand > alpha:
            alpha = stand
        if ply >= 120:
            return alpha
        for move in self.ordered_moves(board, ply, None, captures_only=True):
            board.push(move)
            val = -self.quiesce(board, -beta, -alpha, ply + 1)
            board.pop()
            if val >= beta:
                return beta
            if val > alpha:
                alpha = val
        return alpha

    # -- main negamax --
    def negamax(self, board, depth, alpha, beta, ply):
        self.nodes += 1
        self.check_time()
        if board.is_checkmate():
            return -(MATE - ply)
        if (board.is_stalemate() or board.is_insufficient_material()
                or board.can_claim_fifty_moves()):
            return 0
        if depth <= 0:
            return self.quiesce(board, alpha, beta, ply)

        key = None
        try:
            key = board.transposition_key()
        except Exception:
            key = None
        tt_move = None
        if key is not None and key in self.tt:
            e_depth, e_val, e_flag, e_move = self.tt[key]
            tt_move = e_move
            if e_depth >= depth:
                if e_flag == 0:
                    return e_val
                if e_flag == 1 and e_val >= beta:
                    return e_val
                if e_flag == 2 and e_val <= alpha:
                    return e_val

        best = -INF
        best_move = None
        orig_alpha = alpha
        for move in self.ordered_moves(board, ply, tt_move):
            board.push(move)
            val = -self.negamax(board, depth - 1, -beta, -alpha, ply + 1)
            board.pop()
            if val > best:
                best = val
                best_move = move
            if val > alpha:
                alpha = val
            if alpha >= beta:
                if not board.is_capture(move) and not move.promotion:
                    k = self.killers[ply] if ply < len(self.killers) else None
                    if k is not None and move != k[0]:
                        k[1] = k[0]
                        k[0] = move
                    self.history[move.from_square][move.to_square] += depth * depth
                break
        if key is not None and best_move is not None and abs(best) < MATE - 1000:
            if best <= orig_alpha:
                flag = 2
            elif best >= beta:
                flag = 1
            else:
                flag = 0
            self.tt[key] = (depth, best, flag, best_move)
        return best

    def search(self, board, budget):
        moves = list(board.legal_moves)
        if not moves:
            return None
        if len(moves) == 1:
            return moves[0]
        self.nodes = 0
        self.tt = {}
        self.killers = [[None, None] for _ in range(128)]
        self.history = [[0] * 64 for _ in range(64)]
        self.deadline = time.perf_counter() + budget
        # order root moves: captures/promotions first for a good depth-1 baseline
        scored = [(self.order_score(board, m, 0, None), m) for m in moves]
        scored.sort(key=lambda x: -x[0])
        root = [m for _, m in scored]
        best = root[0]
        depth = 1
        try:
            while True:
                alpha = -INF
                local_best = best
                ordered = sorted(
                    root,
                    key=lambda m: 0 if m == best else 1,
                )
                # keep prior best first, rest in previous order
                for i, m in enumerate(ordered):
                    board.push(m)
                    if i == 0:
                        val = -self.negamax(board, depth - 1, -INF, INF, 1)
                    else:
                        # principal variation search
                        val = -self.negamax(board, depth - 1, -alpha - 1, -alpha, 1)
                        if val > alpha:
                            val = -self.negamax(board, depth - 1, -INF, -alpha, 1)
                    board.pop()
                    if val > alpha:
                        alpha = val
                        local_best = m
                best = local_best
                root = ordered if ordered[0] == best else [best] + [m for m in ordered if m != best]
                # instant return if we found forced mate at this depth
                if alpha >= MATE - 100:
                    break
                depth += 1
                if depth > 64:
                    break
        except Timeout:
            pass
        return best


def parse_position(tokens):
    """tokens: line split after 'position'. Returns (board,)."""
    board = chess.Board()
    if not tokens:
        return board
    if tokens[0] == "startpos":
        board.reset()
        if "moves" in tokens:
            idx = tokens.index("moves")
            for mt in tokens[idx + 1:]:
                try:
                    board.push_uci(mt)
                except Exception:
                    break
        return board
    if tokens[0] == "fen":
        rest = tokens[1:]
        if "moves" in rest:
            idx = rest.index("moves")
            fen_parts = rest[:idx]
            move_parts = rest[idx + 1:]
        else:
            fen_parts = rest
            move_parts = []
        fen = " ".join(fen_parts)
        try:
            board.set_fen(fen)
        except Exception:
            try:
                board = chess.Board(fen)
            except Exception:
                board.reset()
                return board
        for mt in move_parts:
            try:
                board.push_uci(mt)
            except Exception:
                break
        return board
    return board


def main():
    board = chess.Board()
    searcher = Searcher()
    data = sys.stdin
    for line in data:
        line = line.strip()
        if not line:
            continue
        if line == "uci":
            print("id name MyEngine")
            print("id author Muse")
            print("uciok", flush=True)
        elif line == "isready":
            print("readyok", flush=True)
        elif line.startswith("position"):
            tokens = line.split()[1:]
            board = parse_position(tokens)
        elif line.startswith("go"):
            try:
                move = searcher.search(board, TIME_BUDGET)
            except Exception:
                legal = list(board.legal_moves)
                move = legal[0] if legal else None
            if move is None:
                print("bestmove 0000", flush=True)
            else:
                print("bestmove " + move.uci(), flush=True)
        elif line == "quit":
            break
        elif line.startswith("stop"):
            continue


if __name__ == "__main__":
    main()
